import java.time.LocalDate;

public final class Dates {
    public static LocalDate addBusinessDays(LocalDate start, int n) {
        if (n == 0) {
            return start;
        }
        int weeks = n / 5;
        int remainder = n % 5;
        int calendarDays = weeks * 7 + remainder;
        return start.plusDays(calendarDays);
    }
}

