import java.time.DayOfWeek;
import java.time.LocalDate;

public final class DatesTest {
    public static void main(String[] args) {
        checkZeroReturnsStartUnchanged();
        checkFridayPlusOneSkipsWeekend();
        checkMondayPlusFiveLandsNextMonday();
        checkCrossesMonthAndYearBoundary();
        checkStartingOnAWeekendStillCountsCorrectly();
        System.out.println("all tests passed");
    }

    static void checkZeroReturnsStartUnchanged() {
        LocalDate d = LocalDate.of(2024, 6, 1); // Saturday
        if (!Dates.addBusinessDays(d, 0).equals(d)) throw new AssertionError("expected unchanged");
    }

    static void checkFridayPlusOneSkipsWeekend() {
        LocalDate friday = LocalDate.of(2024, 5, 31);
        LocalDate got = Dates.addBusinessDays(friday, 1);
        if (!got.equals(LocalDate.of(2024, 6, 3))) throw new AssertionError("got " + got);
    }

    static void checkMondayPlusFiveLandsNextMonday() {
        LocalDate monday = LocalDate.of(2024, 5, 27);
        LocalDate got = Dates.addBusinessDays(monday, 5);
        if (!got.equals(LocalDate.of(2024, 6, 3))) throw new AssertionError("got " + got);
    }

    static void checkCrossesMonthAndYearBoundary() {
        LocalDate friday = LocalDate.of(2024, 12, 27);
        LocalDate got = Dates.addBusinessDays(friday, 3);
        if (!got.equals(LocalDate.of(2025, 1, 1))) throw new AssertionError("got " + got);
    }

    static void checkStartingOnAWeekendStillCountsCorrectly() {
        LocalDate saturday = LocalDate.of(2024, 6, 1);
        LocalDate got = Dates.addBusinessDays(saturday, 1);
        if (!got.equals(LocalDate.of(2024, 6, 3))) throw new AssertionError("got " + got);
    }
}

